const LIST='delivery-manager-manager-drivers-v1',CURRENT='delivery-manager-manager-v1';
export function savedManagerDrivers(storage){let list=[];try{const value=JSON.parse(storage.getItem(LIST)||'[]');if(Array.isArray(value))list=value.filter(c=>c&&typeof c.id==='string'&&typeof c.token==='string'&&typeof c.key==='string'&&['live','test'].includes(c.mode));}catch{}try{const legacy=JSON.parse(storage.getItem(CURRENT)||'null');if(legacy&&!list.some(c=>c.id===legacy.id)){list.push({...legacy,driverName:legacy.driverName||'Tony'});storage.setItem(LIST,JSON.stringify(list));}}catch{}return list;}
export function rememberManagerDriver(storage,config,name){const driverName=String(name||'').trim().slice(0,40);if(!driverName)throw Error('Enter a driver name.');const list=savedManagerDrivers(storage),saved={...config,driverName},index=list.findIndex(c=>c.id===config.id);if(index<0)list.push(saved);else list[index]=saved;storage.setItem(LIST,JSON.stringify(list));storage.setItem(CURRENT,JSON.stringify(saved));return saved;}
